 "content": "from collections import Counter


def transform(grid):
    """Fill the interiors of hollow rectangular frames; color 6 frames map to 2,
    and the other frame colors map to 7."""
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    counts = Counter(v for row in g for v in row)
    background = counts.most_common(1)[0][0]

    # Identify monochrome components. Each frame is a connected component in a
    # color other than the background and forms the complete perimeter of its box.
    seen = set()
    frames = []
    for r in range(h):
        for c in range(w):
            color = g[r][c]
            if color == background or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for yy, xx in ((y-1, x), (y+1, x), (y, x-1), (y, x+1)):
                    if 0 <= yy < h and 0 <= xx < w and (yy, xx) not in seen and g[yy][xx] == color:
                        seen.add((yy, xx))
                        stack.append((yy, xx))
            rs = [y for y, x in cells]
            cs = [x for y, x in cells]
            top, bottom, left, right = min(rs), max(rs), min(cs), max(cs)
            if bottom - top < 2 or right - left < 2:
                continue
            perimeter = ([(top, x) for x in range(left, right + 1)] +
                         [(bottom, x) for x in range(left, right + 1)] +
                         [(y, left) for y in range(top + 1, bottom)] +
                         [(y, right) for y in range(top + 1, bottom)])
            if all(g[y][x] == color for y, x in perimeter):
                frames.append((top, bottom, left, right, color))

    for top, bottom, left, right, color in frames:
        fill = 2 if color == 6 else 7
        for r in range(top + 1, bottom):
            for c in range(left + 1, right):
                if g[r][c] == background:
                    g[r][c] = fill
    return g
"
