 "content": "from collections import Counter


def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    background = Counter(v for row in g for v in row).most_common(1)[0][0]
    seen, frames = set(), []
    for r in range(h):
        for c in range(w):
            color = g[r][c]
            if color == background or (r, c) in seen:
                continue
            stack, cells = [(r, c)], []
            seen.add((r, c))
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and g[yy][xx] == color:
                        seen.add((yy,xx))
                        stack.append((yy,xx))
            top, bottom = min(y for y,x in cells), max(y for y,x in cells)
            left, right = min(x for y,x in cells), max(x for y,x in cells)
            if bottom-top < 2 or right-left < 2:
                continue
            perimeter = ([(top,x) for x in range(left,right+1)] +
                         [(bottom,x) for x in range(left,right+1)] +
                         [(y,left) for y in range(top+1,bottom)] +
                         [(y,right) for y in range(top+1,bottom)])
            if all(g[y][x] == color for y,x in perimeter):
                frames.append((top,bottom,left,right))
